const listRecentAndUpcomingTournaments = `-- name: ListRecentAndUpcomingTournaments :many

SELECT t.id, t.created_at, t.updated_at, t.deleted_at, t.uuid, t.name, t.description,
    t.directors, t.is_started,
    COALESCE((
        SELECT jsonb_object_agg(d.key, jsonb_set(d.value, '{json}',
            COALESCE(d.value->'json', '{}'::jsonb) - 'pairingMap' - 'standings' - 'matrix' - 'pidxMap'))
        FROM jsonb_each(t.divisions) d
    ), '{}'::jsonb)::jsonb AS divisions,
    t.type, t.parent, t.slug, t.default_settings, t.alias_of, t.is_finished, t.extra_meta,
    t.scheduled_start_time, t.scheduled_end_time, t.created_by
FROM tournaments t
WHERE (t.scheduled_start_time IS NOT NULL AND t.scheduled_start_time BETWEEN $1::timestamptz AND $2::timestamptz)
   OR (t.scheduled_end_time IS NOT NULL AND t.scheduled_end_time BETWEEN $1::timestamptz AND $2::timestamptz)
ORDER BY t.scheduled_start_time ASC
`

type ListRecentAndUpcomingTournamentsParams struct {
	Since pgtype.Timestamptz
	Until pgtype.Timestamptz
}

type ListRecentAndUpcomingTournamentsRow struct {
	ID                 int64
	CreatedAt          pgtype.Timestamptz
	UpdatedAt          pgtype.Timestamptz
	DeletedAt          pgtype.Timestamptz
	Uuid               pgtype.Text
	Name               pgtype.Text
	Description        pgtype.Text
	Directors          []byte
	IsStarted          pgtype.Bool
	Divisions          []byte
	Type               pgtype.Text
	Parent             pgtype.Text
	Slug               pgtype.Text
	DefaultSettings    []byte
	AliasOf            pgtype.Text
	IsFinished         pgtype.Bool
	ExtraMeta          []byte
	ScheduledStartTime pgtype.Timestamptz
	ScheduledEndTime   pgtype.Timestamptz
	CreatedBy          pgtype.Int4
}

// The listing queries select every column of tournaments, in table order, so
// their rows convert to models.Tournament. Their divisions have the bulky
// per-division state stripped out (pairings, standings, the pairing matrix):
// listings only need each division's players and controls, and decoding full
// divisions for every tournament in a listing took about 100 ms. Entities
// loaded from them must never be cached or saved.
func (q *Queries) ListRecentAndUpcomingTournaments(ctx context.Context, arg ListRecentAndUpcomingTournamentsParams) ([]ListRecentAndUpcomingTournamentsRow, error) {
	rows, err := q.db.Query(ctx, listRecentAndUpcomingTournaments, arg.Since, arg.Until)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRecentAndUpcomingTournamentsRow
	for rows.Next() {
		var i ListRecentAndUpcomingTournamentsRow
		if err := rows.Scan(
			&i.ID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.Uuid,
			&i.Name,
			&i.Description,
			&i.Directors,
			&i.IsStarted,
			&i.Divisions,
			&i.Type,
			&i.Parent,
			&i.Slug,
			&i.DefaultSettings,
			&i.AliasOf,
			&i.IsFinished,
			&i.ExtraMeta,
			&i.ScheduledStartTime,
			&i.ScheduledEndTime,
			&i.CreatedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

